cd /opt/nxeon && node -e '
import("./scripts/blog-seed-lib.mjs").then(async ({db})=>{
  const fs=await import("fs");
  const body=fs.readFileSync("scripts/seo-webdev.mjs","utf8");
  const links=[...body.matchAll(/\]\(\/blog\/([a-z0-9-]+)\)/g)].map(m=>m[1]);
  const uniq=[...new Set(links)];
  const rows=await db.blogPost.findMany({select:{slug:true}});
  const known=new Set(rows.map(r=>r.slug));
  const bad=uniq.filter(s=>!known.has(s));
  console.log("distinct blog links:",uniq.length);
  console.log("BAD (404) links:",bad.length?bad:"none");
  await db.$disconnect();
});
'

